function subdivideQuad(_quad, _minSideLength = 20, _divideChange = 0.9) {
    if (_quad.minLength() < _minSideLength) {
        return [_quad];
    }
    else if (random() < _divideChange) // 90% to divide
    {
        if (random() <= 0.5) {
            // divide horizontally
            let topXPercent = random(0.3, 0.7);
            let botXPercent = topXPercent;

            // quad A
            let A_p1 = _quad.p1.copy();
            let A_p2 = lerpPoint(_quad.p1, _quad.p2, topXPercent);
            let A_p3 = lerpPoint(_quad.p4, _quad.p3, botXPercent);
            let A_p4 = _quad.p4.copy();

            let quadAs = subdivideQuad(new PerspectiveQuad(A_p1, A_p2, A_p3, A_p4, randomBuildingHeight()));

            // quad B
            let B_p1 = lerpPoint(_quad.p1, _quad.p2, topXPercent);
            let B_p2 = _quad.p2.copy();
            let B_p3 = _quad.p3.copy();
            let B_p4 = lerpPoint(_quad.p4, _quad.p3, botXPercent);

            let quadBs = subdivideQuad(new PerspectiveQuad(B_p1, B_p2, B_p3, B_p4, randomBuildingHeight()));

            return quadAs.concat(quadBs);
        }
        else
        // divide vertically
        {
            let leftXPercent = random(0.3, 0.7);
            let rightXPercent = leftXPercent;

            // quad A
            let A_p1 = _quad.p1.copy();
            let A_p2 = _quad.p2.copy();
            let A_p3 = lerpPoint(_quad.p2, _quad.p3, rightXPercent);
            let A_p4 = lerpPoint(_quad.p1, _quad.p4, leftXPercent);

            let quadAs = subdivideQuad(new PerspectiveQuad(A_p1, A_p2, A_p3, A_p4, randomBuildingHeight()));

            // quad B
            let B_p1 = lerpPoint(_quad.p1, _quad.p4, leftXPercent);
            let B_p2 = lerpPoint(_quad.p2, _quad.p3, rightXPercent);
            let B_p3 = _quad.p3.copy();
            let B_p4 = _quad.p4.copy();

            let quadBs = subdivideQuad(new PerspectiveQuad(B_p1, B_p2, B_p3, B_p4, randomBuildingHeight()));

            return quadAs.concat(quadBs);
        }
    }
