function splitQuadByMinRectSize(_quad, _unitSize = 30) {
    let unitSize = _unitSize;
    let xCount = ceil(_quad.topLength() / unitSize);
    let yCount = ceil(_quad.leftLength() / unitSize);

    if (xCount == 1 && yCount == 1)
        return [_quad];

    let resultQuads = [];
    for (let x = 0; x < xCount; x++) {
        for (let y = 0; y < yCount; y++) {
            let p1x = lerp(_quad.p1.x, _quad.p2.x, x / xCount);
            let p1y = lerp(_quad.p1.y, _quad.p4.y, y / yCount);

            let p2x = lerp(_quad.p1.x, _quad.p2.x, (x + 1) / xCount);
            let p2y = lerp(_quad.p1.y, _quad.p4.y, y / yCount);

            let p3x = lerp(_quad.p1.x, _quad.p2.x, (x + 1) / xCount);
            let p3y = lerp(_quad.p1.y, _quad.p4.y, (y + 1) / yCount);

            let p4x = lerp(_quad.p1.x, _quad.p2.x, x / xCount);
            let p4y = lerp(_quad.p1.y, _quad.p4.y, (y + 1) / yCount);

            let newQuad = new PerspectiveQuad(
                new Point(p1x, p1y),
                new Point(p2x, p2y),
                new Point(p3x, p3y),
                new Point(p4x, p4y),
                _quad.tall
            );
            newQuad.copyAttributes(_quad);
            resultQuads.push(newQuad);
        }
    }

    return resultQuads;
}

