class PerspectiveQuad {
    constructor(_p1, _p2, _p3, _p4, _tall = 1) {
        this.p1 = _p1;
        this.p2 = _p2;
        this.p3 = _p3;
        this.p4 = _p4;
        this.tall = _tall;

        this.color = new ColorSetting();

        this.wallXCount = 1;
        this.wallYCount = 1;

        this.type = 0; // 0: building, 1: street, 2: race path 
    }

    copyAttributes(_quad) {
        this.wallXCount = _quad.wallXCount;
        this.wallYCount = _quad.wallYCount;
        this.type = _quad.type;
        this.color = _quad.color;
    }

    copy() {
        let newQuad = new PerspectiveQuad(this.p1.copy(), this.p2.copy(), this.p3.copy(), this.p4.copy(), this.tall);
        newQuad.wallXCount = this.wallXCount;
        newQuad.wallYCount = this.wallYCount;
        newQuad.type = this.type;
        newQuad.color = this.color;

        return newQuad;
    }

    isPointIn(_x, _y) {
        if (_x < this.p1.x)
            return false;
        else if (_x > this.p2.x)
            return false;
        else if (_y < this.p1.y)
            return false;
        else if (_y > this.p3.y)
            return false;
        else
            return true;
    }

    centerPos() {
        let rawCenter = new Point((this.p1.x + this.p2.x + this.p3.x + this.p4.x) / 4, (this.p1.y + this.p2.y + this.p3.y + this.p4.y) / 4);

        return rawCenter;
    }

    minLength() {
        return min(this.topLength(), this.bottomLength(), this.leftLength(), this.rightLength());
    }

    topLength() {
        return dist(this.p1.x, this.p1.y, this.p2.x, this.p2.y);
    }

    bottomLength() {
        return dist(this.p3.x, this.p3.y, this.p4.x, this.p4.y);
    }

    leftLength() {
        return dist(this.p1.x, this.p1.y, this.p4.x, this.p4.y);
    }

    rightLength() {
        return dist(this.p2.x, this.p2.y, this.p3.x, this.p3.y);
    }

    drawShape(_p1, _p2, _p3, _p4) {
        let strokeSize = 3;

        let xDist = dist(_p1.x, _p1.y, _p2.x, _p2.y);
        let yDist = dist(_p1.x, _p1.y, _p4.x, _p4.y);

        for (let x = 0; x <= xDist; x += 3) {
            for (let y = 0; y <= yDist; y += 3) {
                let xt = x / xDist;
                let yt = y / yDist;

                let xPos = lerp(_p1.x, _p2.x, xt);
                let yPos = lerp(_p1.y, _p4.y, yt);

                _mainCanvas.circle(xPos, yPos, strokeSize);
            }
        }

    }
}


