class Point {

    constructor(_x = 0, _y = 0) {
        this.x = _x;
        this.y = _y;
    }

    copy() {
        return new Point(this.x, this.y);
    }

    applyPerspective() {
        let x = this.x;
        let y = this.y;

        this.x += (y - 0.5 * height) * 0.6;
        this.y += (x - 0.5 * width) * -0.2;
    }

    applyTall(_tall) {
        this.y -= _tall;
    }
}

function lerpPoint(_p1, _p2, _t) {
    let x = lerp(_p1.x, _p2.x, _t);
    let y = lerp(_p1.y, _p2.y, _t);

    return new Point(x, y);
}

class ColorSetting {
    constructor() {
        this.strokeHue = 0;
        this.strokeSat = 0;
        this.strokeBri = 0;

        this.strokeWeight = 1;

        this.fillHue = 0;
        this.fillSat = 0;
        this.fillBri = 0;
