        tempP1.y -= floorHeight * floorHeightMultiplier;
        tempP2.y -= floorHeight * floorHeightMultiplier;
        tempP3.y -= floorHeight * floorHeightMultiplier;
        tempP4.y -= floorHeight * floorHeightMultiplier;
    }

