    let baseX = _basePoint.x;
    let baseY = _basePoint.y;

    let sideAX = baseX;
    let sideAY = baseY;

    let sideBX = baseX;
    let sideBY = baseY;

    if(_dir == 'X')
    {
        sideAX -= _thickness * 0.5;
        sideBX += _thickness * 0.5;
    }
    else if(_dir == 'Y')
    {
        sideAY -= _thickness * 0.5;
        sideBY += _thickness * 0.5;
    }

    let sideAPoint = new Point(sideAX, sideAY);
    let sideBPoint = new Point(sideBX, sideBY);

    sideAPoint.applyPerspective();
    sideBPoint.applyPerspective();

    sideAPoint.y -= _height;
    sideBPoint.y -= _height;

    let sidePointA = [];
    let sidePointB = [];

    for(let i=0; i< _length; i++)
    {
        angleMode(DEGREES);

        let noiseValue = noise(baseX * noiseScale, baseY * noiseScale);
        let rotValue = lerp(-80, 80, noiseValue);
        baseX += sin(rotValue);
        baseY -= cos(rotValue);

        sideAPoint.x += sin(rotValue);
        sideAPoint.y -= cos(rotValue);

        sideBPoint.x += sin(rotValue);
        sideBPoint.y -= cos(rotValue);

        sidePointA.push(new Point(sideAPoint.x, sideAPoint.y));
        sidePointB.push(new Point(sideBPoint.x, sideBPoint.y));
    }

    beginShape();
    vertex(sidePointB[0].x, sidePointB[0].y);
    vertex(sidePointA[0].x, sidePointA[0].y);

    for(let i=1; i< sidePointA.length; i++)
        vertex(sidePointA[i].x, sidePointA[i].y);

    vertex(sidePointB[sidePointB.length - 1].x, sidePointB[sidePointB.length - 1].y);

    for(let i=sidePointB.length - 2; i>=0; i--)
        vertex(sidePointB[i].x, sidePointB[i].y);

    endShape(CLOSE);
}

