function SortOrderByCubes(_quads) {

  // get a copied array
  let resultArray = [];
  for (let i = 0; i < _quads.length; i++)
    resultArray.push(_quads[i]);

  let xStep = 4;
  let yStep = 4;

  let sortXCount = (width + 2 * canvasPushOut) / xStep;
  let sortYCount = (height + 2 * canvasPushOut) / yStep;

  for (let y = 0; y < sortYCount; y++) {
    for (let x = sortXCount - 1; x > 0; x--) {

      let xPos = xFrom + x * xStep;
      let yPos = yFrom + y * yStep;

      for (let i = 0; i < _quads.length; i++) {
        if (_quads[i].isPointIn(xPos, yPos)) {
          // remove the element and put it in the back
          let index = resultArray.indexOf(_quads[i]);
          resultArray.splice(index, 1);
          resultArray.push(_quads[i]);
        }
      }

    }
  }

  return resultArray;
}

